refentry.refsect1:
&reftitle.description;

 arrayarray_slice
 arrayarray
 intoffset
 intnulllength&null;
 boolpreserve_keys&false;



 array_slice restituisce la sequenza di elementi dell'array
 array specificata dai parametri
 offset e
 length.

&reftitle.returnvalues;


 Restituisce la porzione. Se l'offset è maggiore della dimensione dell'array,
 viene restituito un array vuoto.

  &reftitle.examples;



    Esempi di array_slice


<?php
$input = array("a", "b", "c", "d", "e");

$output = array_slice($input, 2);      // restituisce "c", "d" ed "e"
$output = array_slice($input, -2, 1);  // restituisce "d"
$output = array_slice($input, 0, 3);   // restituisce "a", "b" e "c"

// si notino le differenze nelle chiavi dell'array
print_r(array_slice($input, 2, -1));
print_r(array_slice($input, 2, -1, true));
?>


    &example.outputs;


Array
(
    [0] => c
    [1] => d
)
Array
(
    [2] => c
    [3] => d
)







    array_slice e array con base uno


<?php
$input = array(1 => "a", "b", "c", "d", "e");
print_r(array_slice($input, 1, 2));
?>


    &example.outputs;


Array
(
    [0] => b
    [1] => c
)







    array_slice e array con chiavi miste


<?php
$ar = array('a'=>'mela', 'b'=>'banana', '42'=>'pera', 'd'=>'arancia');
print_r(array_slice($ar, 0, 3));
print_r(array_slice($ar, 0, 3, true));
?>


    &example.outputs;


Array
(
    [a] => mela
    [b] => banana
    [0] => pera
)
Array
(
    [a] => mela
    [b] => banana
    [42] => pera
)
